from mk import *

def fig():
    g = Fig(560, 220, "תרשים א: שני גופים A ו-B צמודים זה לזה על משטח אופקי, וכוח F דוחף את A. תרשים ב: גוף B מונח על גוף A, וכוח F דוחף את A")
    g.ground(30, 260, 110)
    g.block(130, 88, 44, 44, "A"); g.block(172, 92, 36, 36, "B"); g.arrow(60, 80, 106, 80, "F", lx=70, ly=70)
    g.heb(150, 140, "תרשים א")
    g.ground(300, 530, 190)
    g.block(400, 168, 50, 44, "A"); g.block(400, 128, 36, 36, "B"); g.arrow(330, 160, 373, 160, "F", lx=340, ly=150)
    g.heb(420, 214, "תרשים ב")
    return g

E(id="bagrut-2009-q2", year=2009, label="2009 שאלה 2", topic="dynamics", sub="dyn-friction", diff=3, fig=fig,
  stem=r"שני גופים, $A$ ו-$B$, צמודים זה לזה, ומונחים על משטח אופקי לא חלק. ברגע מסוים מפעילים על גוף $A$ כוח אופקי קבוע $F$, כמתואר בתרשים א, והגופים מתחילים לנוע ימינה.",
  parts=[
    P("א", r"האם הכוח שגוף $A$ מפעיל על גוף $B$, בזמן תנועת הגופים, גדול מהכוח שגוף $B$ מפעיל על גוף $A$, קטן ממנו או שווה לו? נמק את תשובתך.", choice(["גדול", "קטן", "שווה"], 2), ["principle"], [
        S(r"החוק השלישי של ניוטון", r"כוחות של שני גופים זה על זה תמיד שווים בגודלם והפוכים בכיוונם, גם בתאוצה", r"\vec F_{AB} = -\vec F_{BA}"),
    ], r"שווה", key=r"שווים, לפי החוק השלישי"),
    P("ב", r"נתון: $m_B = 2\,\text{kg}$, $m_A = 3\,\text{kg}$, $F = 13\,\text{N}$. מקדם החיכוך הקינטי בין כל גוף למשטח $\mu_k = 0.1$. חשב את הכוח שגוף $A$ מפעיל על גוף $B$.", num(5.2, "N"), ["fbd", "principle", "algebra"], [
        S(r"תאוצת המערכת", r"החיכוך על שני הגופים יחד: $\mu(m_A + m_B)g = 5\,\text{N}$", r"a = \frac{13 - 5}{5} = 1.6\,\text{m/s}^2"),
        S(r"החוק השני ל-$B$", r"על $B$ פועלים הכוח מ-$A$ קדימה והחיכוך אחורה", r"F_{AB} - \mu m_B g = m_B a"),
        S(r"מציבים", r"מבודדים את F_AB", r"F_{AB} = 2 \cdot 1.6 + 0.1 \cdot 20 = 5.2\,\text{N}"),
    ], r"$5.2\,\text{N}$", key=r"5.2 N"),
    P("ג", r"הכוח $F$ פועל במשך כמה שניות בלבד. אחרי שהכוח $F$ מפסיק לפעול, מהו הכוח שגוף $A$ מפעיל על גוף $B$? פרט את תשובתך (התייחס לגופים כאל גופים קשיחים).", num(0, "N"), ["fbd", "principle"], [
        S(r"אם כל גוף היה נע לבד", r"כל אחד מאט רק בגלל החיכוך שלו", r"a_A = a_B = -\mu g = -1\,\text{m/s}^2"),
        S(r"מסקנה", r"לשניהם אותה האטה בלי לדחוף זה את זה, ולכן אין כוח ביניהם", r"F_{AB} = 0"),
    ], r"$0$: לשני הגופים אותה האטה, $\mu g$"),
    P("ד", r"לפניך שלושה היגדים. קבע מהו ההיגד הנכון, ונמק את תשובתך. (1) ברגע שהכוח $F$ מפסיק לפעול, שני הגופים נעצרים מיד. (2) אחרי שהכוח $F$ מפסיק לפעול, שני הגופים ייעצרו כעבור אותו זמן (גדול מ-$0$). (3) אחרי שהכוח $F$ מפסיק לפעול, גוף $A$ ייעצר מוקדם יותר מגוף $B$.", choice(["(1)", "(2)", "(3)"], 2), ["principle", "understanding"], [
        X(r"בזמן הדחיפה הגופים נלחצים מעט זה אל זה (כמו קפיץ קטן ביניהם), כי $A$ דוחף את $B$."),
        S(r"כשהכוח מפסיק", r"ה\"קפיץ\" הדחוס משתחרר: דוחף את $B$ קדימה ואת $A$ אחורה", r"F_k:\ A \leftarrow,\ B \rightarrow"),
        S(r"מסקנה", r"$A$ מאט יותר ונעצר קודם, ו-$B$ ממשיך קצת יותר", r"t_A < t_B"),
    ], r"(3), לפי המפתח: הגופים נלחצים זה לזה בזמן הדחיפה, וההתפרקות דוחפת את $B$ קדימה", key=r"(3)"),
    P("ה", r"במקרה אחר, מדביקים את גוף $B$ על גוף $A$ (תרשים ב). מפעילים על גוף $A$ כוח ששווה לכוח הנתון בסעיף ב. האם תאוצת הגופים $A$ ו-$B$ במצב זה גדולה מתאוצת הגופים במצב שמתואר בסעיף ב, שווה לה או קטנה ממנה? נמק.", choice(["גדולה", "שווה", "קטנה"], 1), ["fbd", "principle"], [
        S(r"החיכוך", r"הנורמלי על המשטח הוא כל המשקל, כמו קודם", r"f = \mu(m_A + m_B)g = 5\,\text{N}"),
        S(r"התאוצה", r"אותו כוח, אותו חיכוך, אותה מסה", r"a = \frac{13 - 5}{5} = 1.6\,\text{m/s}^2"),
    ], r"שווה", key=r"התאוצות שוות"),
  ],
  concepts=["החוק השלישי של ניוטון", "כוח מגע בין גופים", "חיכוך קינטי", "מערכת גופים"],
  summary=r"שני גופים שנדחפים יחד על משטח עם חיכוך: הכוח ביניהם, מה קורה כשהדחיפה נפסקת, ולמה ערימה אחת על השנייה לא משנה את התאוצה.",
  review='צריך החלטה שלך, בסעיפים ג ו-ד.\nסעיף ג שואל איזה כוח גוף A מפעיל על גוף B אחרי שהכוח F מפסיק. אם הגופים קשיחים, התשובה 0: כל גוף מאט לבד באותה תאוצה, והם לא דוחפים זה את זה.\nבסעיף ד, דף התשובות בוחר בהיגד (3) ("A ייעצר לפני B") ומסביר בדחיסה קטנה בין הגופים, כאילו הם קפיצים. זה לא מתיישב עם 0 בסעיף ג.\nאצלי: כתבתי 0 בסעיף ג ואת ההיגד של דף התשובות בסעיף ד.\nמה לבדוק: איך אתה מלמד את זה, ואיזו תשובה אתה רוצה בסעיף ד. כתוב לי ואתקן.')
